/* global EyeDropper */
var colorDraw = {
  config: {
    canvasScale: 2,
    // canvas 放大倍数，太大有性能问题
    viewScale: 8 // 放大镜倍数
  },
  init: function init(colorPicker) {
    // 隐藏 title
    var hoverTip = document.querySelector('.po-hover-tip');
    if (hoverTip) hoverTip.style.display = 'none';
    // 支持 EyeDropper API
    if (window.EyeDropper) {
      var eyeDropper = new EyeDropper();
      eyeDropper.open().then(function (result) {
        var val = result.sRGBHex.replace(/[^\da-fA-F]/g, '').toUpperCase();
        var inputHex = colorPicker.picker.querySelector('.input_box .input_hex');
        if (inputHex) inputHex.value = val;
        colorPicker.setColorByInput('input_hex', val);
        colorPicker.selectColor(colorPicker.data.rgba);
      }).catch(function () {
        return console.log('EyeDropper 错误');
      });
      return;
    }
  }
};
