class GlobalToolbar extends Toolbar {
  editor;
  constructor(options = {}) {
    // 必选参数校验
    if (!options.editor || !options.container) {
      throw new Error('必须提供 editor 和 container 参数');
    }
    const items = [{
      type: 'button',
      name: 'theme',
      icon: '<i class="smart-iconfont">&#xe6cb;</i>',
      'po-ul-lib-original-title': '节点风格'
    }, {
      type: 'button',
      name: 'layout',
      icon: '<i class="smart-iconfont">&#xeabb;</i>',
      'po-ul-lib-original-title': '节点布局'
    }];
    const defaultHandlers = {
      theme: e => {
        this.editor.clearSelected();
        const target = e.currentTarget;
        let themePanel;
        const drowdown = new Dropdown({
          className: 'theme-dropdown-menu',
          target,
          offsetGap: {
            y: 4
          },
          shouldCloseOnOutsideClick: e => {
            const themePanelRootCls = themePanel?.getRootNode()?.className;
            if (themePanelRootCls) {
              return !e.target.closest(`.${themePanelRootCls}`);
            }
            return !(e.target.closest('[dropdown=true]') || e.target.getAttribute('dropdown'));
          },
          createElementFn: ul => {
            themePanel = new ThemeMenu(ul);
            themePanel.on('onSelect', theme => {
              const changedInfo = {
                shape: {
                  style: {
                    fill: theme.fill,
                    stroke: theme.stroke
                  },
                  textStyle: {
                    color: theme.color
                  }
                }
              };
              // 使用组合操作：清空自定义样式 + 更新全局配置
              this.editor.updateConfigWithRemoveOverrides(changedInfo, {
                scopes: ['shape.style', 'shape.textStyle', 'linker']
              });
              themePanel = undefined;
              drowdown.close();
            });
          }
        });
      },
      layout: e => {
        this.editor.clearSelected();
        let shapeMenuPanel;
        const drowdown = new Dropdown({
          className: 'layout-panel-wrapper',
          target: e.currentTarget,
          offsetGap: {
            y: 4
          },
          shouldCloseOnOutsideClick: e => {
            const shapeMenuPanelCls = shapeMenuPanel?.getRootNode()?.className;
            if (shapeMenuPanelCls) {
              return !e.target.closest(`.${shapeMenuPanelCls}`);
            }
            return !(e.target.closest('[dropdown=true]') || e.target.getAttribute('dropdown'));
          },
          createElementFn: ul => {
            const {
              shape: shapeConfig
            } = this.editor.getConfig();
            shapeMenuPanel = new ShapeMenu({
              shapeTypeSelected: shapeConfig.type
            }, ul);
            shapeMenuPanel.on('onSelectShapeType', item => {
              const changedInfo = {
                shape: {
                  type: item.value
                }
              };
              // 使用组合操作：清空自定义布局 + 更新全局配置
              this.editor.updateConfigWithRemoveOverrides(changedInfo, {
                scopes: ['shape.type', 'shape.width', 'shape.height']
              });
              shapeMenuPanel = undefined;
              drowdown.close();
            });
          }
        });
      }
    };
    // ✅ 使用 Toolbar 的 mergeItems
    const mergedItems = Toolbar.mergeItems(items, options.items || []);
    const mergedHandlers = {
      ...defaultHandlers,
      ...(options.handlers || {})
    };
    super(options.container, {
      ...options,
      className: `smart-orgchart-global-toolbar${options.className ? ' ' + options.className : ''}`,
      items: mergedItems,
      handlers: mergedHandlers
    });
    this.editor = options.editor;
  }
  destroy() {
    super.destroy();
    this.editor = null;
  }
}
