class Section extends events.EventEmitter {
  constructor(options) {
    super();
    this._locale = options.locale;
    return this.render(...arguments);
  }
  render(options) {
    const {
      content,
      contentX,
      contentY,
      contentW,
      contentH,
      bgFill,
      sectionTextStyle,
      sectionBgStyle: {
        fill
      },
      adaptiveBgColor,
      onChange = () => {}
    } = options;
    const text = content?.text;
    const classNames = [CLASS_LAYER_SECTION_TITLE];
    if (!text) {
      classNames.unshift(CLASS_LAYER_SECTION_TITLE_PLACEHOLDER);
    }
    const _fill = fill || bgFill;
    let color = sectionTextStyle.color;
    let placeholderColor = sectionTextStyle.placeholderColor || sectionTextStyle.color;
    if (adaptiveBgColor) {
      const isLight = isLightColor(_fill === 'transparent' ? '#FFF' : _fill || '#FFF');
      color = isLight ? sectionTextStyle.colorDark : sectionTextStyle.color;
      placeholderColor = (isLight ? sectionTextStyle.placeholderColorDark : sectionTextStyle.placeholderColor) || color;
    }
    const _selfStyle = content?.style || {};
    const _content = new RichText({
      className: classNames.join(' '),
      x: contentX,
      y: contentY,
      text,
      style: {
        ...sectionTextStyle,
        ..._selfStyle,
        width: contentW,
        height: contentH,
        color,
        placeholderColor,
        placeholder: this._locale.get('section.placeholder'),
        cursor: 'text'
      },
      onChange
    });
    return _content.getElement();
  }
}
;// ./src/packages/pyramid/section/sectionBlock.js



class SectionBlock extends Section {
  constructor() {
    super(...arguments);
  }
  render(options) {
    const group = new draw_esm_min_ge({
      zIndex: -1
    });
    const bg = this.renderBackground(options);
    const text = super.render(options);
    group.add(bg);
    group.add(text);
    return group;
  }
  renderBackground(options) {
    const {
      bgX,
      bgY,
      bgHeight,
      bgWidth,
      bgFill,
      origin = 'center',
      skewX = 0,
      sectionBgStyle: {
        fill
      }
    } = options;
    const points = [bgX, bgY, bgX + bgWidth, bgY, bgX + bgWidth, bgY + bgHeight, bgX, bgY + bgHeight];
    const _fill = fill || bgFill;
    return new draw_esm_min_Me({
      className: CLASS_LAYER_SECTION_BG,
      points,
      fill: _fill,
      origin,
      skewX
    });
  }
}
;// ./src/packages/pyramid/section/sectionLineCircle.js



class SectionLineCircle extends Section {
  constructor() {
    super(...arguments);
  }
  render(options) {
    const group = new draw_esm_min_ge({
      zIndex: -1
    });
    const bg = this.renderBackground(options);
    const text = super.render(options);
    group.add(bg);
    group.add(text);
    return group;
  }
  renderBackground(options) {
    const {
      bgX,
      bgY,
      bgHeight,
      bgWidth,
      bgFill,
      sectionBgStyle: {
        fill,
        lineStroke,
        dashPattern = [2, 2],
        circleSize = 10
      }
    } = options;
    const centerY = bgY + bgHeight / 2;
    const group = new draw_esm_min_ge({
      className: CLASS_LAYER_SECTION_BG
    });
    const _fill = fill || bgFill;
    const _stroke = lineStroke || bgFill;
    const line = new draw_esm_min_Ze({
      points: [bgX, centerY, bgX + bgWidth, centerY],
      stroke: _stroke,
      dashPattern
    });
    const circle = new draw_esm_min_Fe({
      x: bgX + bgWidth - circleSize,
      y: centerY - circleSize / 2,
      width: circleSize,
      height: circleSize,
      fill: _fill
    });
    group.add(line);
    group.add(circle);
    return group;
  }
}
