class SectionLineArrow extends Section {
  constructor() {
    super(...arguments);
  }
  render(options) {
    const group = new draw_esm_min_ge({
      zIndex: -1
    });
    const bg = this.renderBackground(options);
    const text = super.render(options);
    group.add(bg);
    group.add(text);
    return group;
  }
  renderBackground(options) {
    const {
      bgX,
      bgY,
      bgHeight,
      bgFill,
      sectionBgStyle: {
        lineStroke,
        arrowSize = 10,
        lineWidth = 200
      }
    } = options;
    const centerY = bgY + bgHeight / 2;
    const linePath = `M${bgX} ${centerY} L ${bgX + lineWidth} ${centerY} Z`;
    const arrowPath = `M${bgX + lineWidth} ${centerY} L${bgX + lineWidth} ${centerY - Math.abs(arrowSize / 2)}
    L ${bgX + lineWidth + arrowSize} ${centerY}
    L ${bgX + lineWidth} ${centerY + Math.abs(arrowSize / 2)} Z`;
    const _stroke = lineStroke || bgFill;
    return new draw_esm_min_hi({
      className: CLASS_LAYER_SECTION_BG,
      path: linePath + arrowPath,
      fill: _stroke,
      stroke: _stroke
    });
  }
}
