class SectionHelper {
  constructor(options, pyraminInstance) {
    switch (options.sectionBgType) {
      case SECTION_BG_TYPE_MAP.lineCircle:
        {
          return this.renderLineCircle(options, pyraminInstance);
        }
      case SECTION_BG_TYPE_MAP.lineArrow:
        {
          return this.renderLineArrow(options, pyraminInstance);
        }
      case SECTION_BG_TYPE_MAP.lineCircleTurn:
        {
          return this.renderLineCircleTrun(options, pyraminInstance);
        }
      case SECTION_BG_TYPE_MAP.lineCircleThrough:
        {
          return this.renderLineCircleThrough(options, pyraminInstance);
        }
      case SECTION_BG_TYPE_MAP.blockFill:
        {
          return this.renderBlockFill(options, pyraminInstance);
        }
      case SECTION_BG_TYPE_MAP.blockShadow:
        {
          return this.renderBlockShadow(options, pyraminInstance);
        }
      case SECTION_BG_TYPE_MAP.blockBlender:
        {
          return this.renderBlockBlender(options, pyraminInstance);
        }
      default:
        {
          return this.render(options, pyraminInstance);
        }
    }
  }
  render(options, pyraminInstance) {
    const {
      contentX: _contentX,
      contentW: _contentW,
      sectionGap
    } = options;
    const {
      frt,
      frb
    } = pyraminInstance._calcLayerShapeBoundPoints(options);
    const {
      offsetX,
      offsetY
    } = pyraminInstance._getLayerSectionOffset(options);
    const contentX = Math.max(frt.x, frb.x) + offsetX + sectionGap;
    const contentY = Math.min(frt.y, frb.y) + offsetY;
    const contentH = Math.abs(frt.y - frb.y);
    const contentW = _contentW - (contentX - _contentX);
    return new Section({
      ...options,
      contentX,
      contentY,
      contentW,
      contentH,
      locale: pyraminInstance._locale
    });
  }
  renderLineArrow(options, pyraminInstance) {
    const {
      contentX: _contentX,
      contentW: _contentW,
      fill,
      sectionGap,
      sectionBgStyle: {
        lineWidth,
        arrowSize: arrowSize
      }
    } = options;
    const {
      offsetX,
      offsetY
    } = pyraminInstance._getLayerSectionOffset(options);
    const {
      frt,
      frb,
      frc
    } = pyraminInstance._calcLayerShapeBoundPoints(options);
    const bgX = frc.x + offsetX;
    const bgY = Math.min(frt.y, frb.y) + offsetY;
    const bgLineWidth = lineWidth;
    const bgHeight = Math.abs(frt.y - frb.y);
    const contentX = frc.x + lineWidth + arrowSize + offsetX + sectionGap;
    const contentY = bgY;
    const contentW = _contentW - (contentX - _contentX);
    const contentH = bgHeight;
    return new SectionLineArrow({
      ...options,
      contentX,
      contentY,
      contentW,
      contentH,
      bgX,
      bgY,
      bgLineWidth,
      bgHeight,
      bgFill: fill,
      arrowSize,
      locale: pyraminInstance._locale
    });
  }
  renderLineCircle(options, pyraminInstance) {
    const {
      contentX: _contentX,
      contentW: _contentW,
      fill,
      sectionGap
    } = options;
    const {
      _drawBoxBounds
    } = pyraminInstance;
    const {
      offsetX,
      offsetY
    } = pyraminInstance._getLayerSectionOffset(options);
    const {
      frt: frt,
      frb: frb,
      frc: frc
    } = pyraminInstance._calcLayerShapeBoundPoints(options);
    const bgX = Math.min(frt.x, frb.x) + offsetX;
    const bgY = Math.min(frt.y, frb.y) + offsetY;
    const bgWidth = _drawBoxBounds.width - bgX;
    const bgHeight = Math.abs(frt.y - frb.y);
    const contentX = Math.max(frc.x, frt.x) + offsetX + sectionGap;
    const contentY = bgY;
    const contentW = _contentW - (contentX - _contentX);
    const contentH = bgHeight / 2;
    return new SectionLineCircle({
      ...options,
      contentX,
      contentY,
      contentW,
      contentH,
      bgX,
      bgY,
      bgWidth,
      bgHeight,
      bgFill: fill,
      locale: pyraminInstance._locale
    });
  }
  renderLineCircleTrun(options, pyraminInstance) {
    const {
      layerIndex,
      sectionGap,
      sectionBgStyle: {
        fill: bgFill,
        lineWidth,
        circleSize: _circleSize
      },
      sectionPos,
      fill
    } = options;
    const {
      _drawBoxBounds
    } = pyraminInstance;
    const {
      flt,
      flb,
      flc,
      frc
    } = pyraminInstance._calcLayerShapeBoundPoints(options);
    const {
      offsetX,
      offsetY
    } = pyraminInstance._getLayerSectionOffset(options);
    const _fill = bgFill || fill;
    // 画布中心点
    const canvasCX = _drawBoxBounds.width / 2;
    /**
     * 兼容pyramid3d
     * 背景线的起始点应该在画布中心点，但是由于3d图形画布的中心点有可能不在图形上，
     * 所以取每一层的中心点，然后计算偏移
     * */
    const bgX = Math.abs(flc.x + frc.x) / 2 + offsetX;
    const centerOffset = canvasCX - bgX;
    let centerY = frc.y + offsetY;
    let bgLineWidth = lineWidth;
    let circleSize = _circleSize;
    let contentX;
    // 宽度固定
    const contentW = _drawBoxBounds.width / 2 - bgLineWidth - sectionGap;
    let contentH = Math.abs(flt.y - flb.y);
    let contentY;
    let textAlign = 'left';
    let factor = 0;
    if (sectionPos === 'odd') {
      factor = 0;
    } else if (sectionPos === 'even') {
      factor = 1;
    }
    if (layerIndex % 2 === factor) {
      bgLineWidth -= centerOffset;
      bgLineWidth *= -1;
      circleSize *= -1;
      centerY = flc.y + offsetY;
      contentX = 0;
      contentY = centerY - contentH / 2;
      textAlign = 'right';
    } else {
      bgLineWidth += centerOffset;
      contentX = bgX + bgLineWidth + sectionGap;
      contentY = centerY - contentH / 2;
    }
    return new SectionLineCircle({
      ...options,
      contentX,
      contentY,
      contentW,
      contentH,
      textAlign,
      bgX,
      bgY: contentY,
      bgHeight: contentH,
      bgWidth: bgLineWidth,
      bgLineWidth,
      bgFill: _fill,
      sectionBgStyle: {
        ...options.sectionBgStyle,
        circleSize
      },
      locale: pyraminInstance._locale
    });
  }
  renderLineCircleThrough(options, pyraminInstance) {
    const {
      fill,
      layerCount,
      sectionGap,
      layerIndex,
      inverted,
      offset,
      shapeLayout
    } = options;
    const {
      _drawBoxBounds,
      _layerGapWidth
    } = pyraminInstance;
    const {
      flt,
      flb,
      flc
    } = pyraminInstance._calcLayerShapeBoundPoints(options);
    const {
      offsetX,
      offsetY
    } = pyraminInstance._getLayerSectionOffset(options);
    const bgX = 0;
    const bgY = flt.y + offsetY;
    let bgStepOffset = (layerCount - 1 - layerIndex) * (offset + _layerGapWidth) / 2;
    if (inverted) {
      bgStepOffset = layerIndex * (offset + _layerGapWidth) / 2;
    }
    if (shapeLayout === 'right') {
      // 直方图右对齐特殊情况
      bgStepOffset = 0;
    }
    const bgWidth = _drawBoxBounds.width - bgStepOffset;
    const bgHeight = Math.abs(flt.y - flb.y);
    const contentX = bgX;
    const contentH = Math.abs(flt.y - flb.y) / 2;
    const contentY = flt.y + offsetY;
    const contentW = offsetX + Math.min(flt.x, flc.x) - sectionGap;
    return new SectionLineCircle({
      ...options,
      contentX,
      contentY,
      contentW,
      contentH,
      bgX,
      bgY,
      bgWidth,
      bgHeight,
      bgFill: fill,
      locale: pyraminInstance._locale
    });
  }
  renderBlockFill(options, pyraminInstance) {
    const {
      contentX: _contentX,
      contentW: _contentW,
      fill,
      sectionGap,
      layerIndex,
      layerCount,
      sectionBgStyle: {
        stepOffset = 0
      },
      inverted
    } = options;
    const {
      _drawBoxBounds
    } = pyraminInstance;
    const {
      frt,
      frb,
      ftc,
      fbc
    } = pyraminInstance._calcLayerShapeBoundPoints(options);
    const {
      offsetX,
      offsetY
    } = pyraminInstance._getLayerSectionOffset(options);
    let bgStepOffset = (layerCount - 1 - layerIndex) * stepOffset;
    if (inverted) {
      bgStepOffset = layerIndex * stepOffset;
    }
    const bgX = Math.min(ftc.x, fbc.x) + offsetX;
    const bgY = Math.min(frt.y, frb.y) + offsetY;
    const bgWidth = _drawBoxBounds.width - bgX - bgStepOffset;
    const bgHeight = Math.abs(frt.y - frb.y);
    const contentX = Math.max(frt.x, frb.x) + offsetX + sectionGap;
    const contentY = bgY;
    let contentW = _contentW - (contentX - _contentX) - bgStepOffset;
    const contentH = bgHeight;
    return new SectionBlock({
      ...options,
      contentX,
      contentY,
      contentW,
      contentH,
      bgX,
      bgY,
      bgWidth,
      bgHeight,
      bgFill: fill,
      locale: pyraminInstance._locale
    });
  }
  renderBlockShadow(options, pyraminInstance) {
    const {
      fill: _fill,
      sectionGap
    } = options;
    const {
      _drawBoxBounds
    } = pyraminInstance;
    const {
      frt,
      frb
    } = pyraminInstance._calcLayerShapeBoundPoints(options);
    const {
      offsetX,
      offsetY
    } = pyraminInstance._getLayerSectionOffset(options);
    const skewX = -45;
    const bgY = frt.y;
    const bgHeight = Math.abs(frt.y - frb.y);
    const skewOffsetX = Math.cos(degreesToRadians(skewX)) * bgHeight;
    const bgX = skewOffsetX / 2;
    const bgWidth = _drawBoxBounds.width - skewOffsetX;
    const contentH = Math.abs(frt.y - frb.y);
    const contentX = Math.max(frb.x, frt.x) + sectionGap + offsetX;
    const contentY = frt.y + offsetY;
    const contentW = _drawBoxBounds.width - contentX;
    const fill = blendColors(_fill, '#ffffff', 0.85);
    return new SectionBlock({
      ...options,
      contentX,
      contentY,
      contentW,
      contentH,
      bgX,
      bgY,
      bgWidth,
      bgHeight,
      bgFill: fill,
      skewX,
      locale: pyraminInstance._locale
    });
  }
  renderBlockBlender(options, pyraminInstance) {
    const {
      fill: _fill,
      sectionGap
    } = options;
    const {
      flt,
      flb,
      ftc
    } = pyraminInstance._calcLayerShapeBoundPoints(options);
    const {
      offsetX,
      offsetY
    } = pyraminInstance._getLayerSectionOffset(options);
    const bgX = 0;
    const bgY = flt.y + offsetY;
    const bgWidth = offsetX + ftc.x;
    const bgHeight = Math.abs(flt.y - flb.y);
    const contentX = bgX;
    const contentH = Math.abs(flt.y - flb.y);
    const contentY = flt.y + offsetY;
    const contentW = Math.min(flt.x, flb.x) + offsetX - sectionGap;
    const fill = blendColors(_fill, '#ffffff', 0.85);
    return new SectionBlock({
      ...options,
      contentX,
      contentY,
      contentW,
      contentH,
      bgX,
      bgY,
      bgWidth,
      bgHeight,
      bgFill: fill,
      locale: pyraminInstance._locale
    });
  }
}
